mapper.select:
select sku_id, coalesce(sum(stock - stock_locked), 0) as stock from wms_ware_sku where sku_id in
#{skuId}
group by sku_id

mapper.update:
update wms_ware_sku
set stock_locked = stock_locked + #{num}
where id = #{id}
  and stock - stock_locked >= #{num}

update wms_ware_sku
set stock_locked = stock_locked - #{num}
where id = #{id}
  and stock_locked >= #{num}
